CREATE TABLE public.C_POS_InvoiceCardSettlement (AD_Client_ID NUMERIC(10) NOT NULL, AD_Org_ID NUMERIC(10) NOT NULL, Amount NUMERIC NOT NULL, BookingAttempts NUMERIC(10) DEFAULT 0 NOT NULL, Cashier_ID NUMERIC(10) NOT NULL, C_BPartner_ID NUMERIC(10), C_Currency_ID NUMERIC(10) NOT NULL, C_Invoice_ID NUMERIC(10) NOT NULL, C_Payment_ID NUMERIC(10), C_POS_ID NUMERIC(10) NOT NULL, C_POS_InvoiceCardSettlement_ID NUMERIC(10) NOT NULL, Created TIMESTAMP WITH TIME ZONE NOT NULL, CreatedBy NUMERIC(10) NOT NULL, ErrorMsg TEXT, IsAbandoned CHAR(1) DEFAULT 'N' CHECK (IsAbandoned IN ('Y','N')) NOT NULL, IsActive CHAR(1) CHECK (IsActive IN ('Y','N')) NOT NULL, Note TEXT, Status VARCHAR(2) DEFAULT 'PE' NOT NULL, SUMUP_Transaction_ID NUMERIC(10), Updated TIMESTAMP WITH TIME ZONE NOT NULL, UpdatedBy NUMERIC(10) NOT NULL, CONSTRAINT C_POS_InvoiceCardSettlement_Key PRIMARY KEY (C_POS_InvoiceCardSettlement_ID), CONSTRAINT Cashier_CPOSInvoiceCardSettlement FOREIGN KEY (Cashier_ID) REFERENCES public.AD_User DEFERRABLE INITIALLY DEFERRED, CONSTRAINT CBPartner_CPOSInvoiceCardSettlement FOREIGN KEY (C_BPartner_ID) REFERENCES public.C_BPartner DEFERRABLE INITIALLY DEFERRED, CONSTRAINT CCurrency_CPOSInvoiceCardSettlement FOREIGN KEY (C_Currency_ID) REFERENCES public.C_Currency DEFERRABLE INITIALLY DEFERRED, CONSTRAINT CInvoice_CPOSInvoiceCardSettlement FOREIGN KEY (C_Invoice_ID) REFERENCES public.C_Invoice DEFERRABLE INITIALLY DEFERRED, CONSTRAINT CPayment_CPOSInvoiceCardSettlement FOREIGN KEY (C_Payment_ID) REFERENCES public.C_Payment DEFERRABLE INITIALLY DEFERRED, CONSTRAINT CPOS_CPOSInvoiceCardSettlement FOREIGN KEY (C_POS_ID) REFERENCES public.C_POS DEFERRABLE INITIALLY DEFERRED, CONSTRAINT CreatedBy_CPOSInvoiceCardSettlement FOREIGN KEY (CreatedBy) REFERENCES public.AD_User DEFERRABLE INITIALLY DEFERRED, CONSTRAINT SUMUPTransaction_CPOSInvoiceCardSettlement FOREIGN KEY (SUMUP_Transaction_ID) REFERENCES public.SUMUP_Transaction DEFERRABLE INITIALLY DEFERRED, CONSTRAINT UpdatedBy_CPOSInvoiceCardSettlement FOREIGN KEY (UpdatedBy) REFERENCES public.AD_User DEFERRABLE INITIALLY DEFERRED)
;
ALTER TABLE C_POS_InvoiceCardSettlement ADD CONSTRAINT C_POS_InvoiceCardSettlement_Status_Check CHECK (Status IN ('PE','UN','AP','BE','SU','CR','RF','FA','CA','AB'))
;
